sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || !newValue) {
        return;
    }

    var ga = new GlideAjax('x_2137028_validp_0.CheckParkingSlot');
    ga.addParam('sysparm_name', 'checkSlot'); // Name of the method in your Script Include
    ga.addParam('sysparm_slot_id', newValue);  // Pass selected parking slot sys_id

    ga.getXMLAnswer(function(response) {
        if (response == 'occupied') {
            g_form.clearValue('parking_slot');
            g_form.addErrorMessage('This parking slot is already occupied. Please select another slot.');
        } else if (response == 'available') {
            g_form.addInfoMessage('Parking slot is available.');
        }
    });
}
